-- Isolated synthetic database only. Every case is rolled back.
begin;
create function pg_temp.require(ok boolean,label text) returns void language plpgsql as $$begin if ok is distinct from true then raise exception 'Project history test failed: %',label;end if;end$$;
do $$
declare leader uuid:=gen_random_uuid();member uuid:=gen_random_uuid();candidate uuid:=gen_random_uuid();outsider uuid:=gen_random_uuid();p uuid:=gen_random_uuid();v uuid;conversation uuid:=gen_random_uuid();secret_group uuid:=gen_random_uuid();task uuid;period uuid;stage uuid;request uuid;concept uuid;label text;message_notice uuid:=gen_random_uuid();other_notice uuid:=gen_random_uuid();snapshot jsonb;form jsonb;failed boolean;count_before integer;
begin
 perform pg_temp.require((select count(*)=1 and bool_and(not open) from project_vacancies where project_id=(select id from projects where slug='p37-historico')),'residual historic vacancies closed');
 perform pg_temp.require((select status='closed' and closure_reason='project_completed' and message='Preserve application' from join_requests where project_id=(select id from projects where slug='p37-historico')),'legacy pending candidacy closed without rejection');
 perform pg_temp.require((select closed_at is null and status='completed' from projects where slug='p37-historico'),'no invented legacy completion date or status conversion');
 perform lifecycle_private.close_recruitment((select id from projects where slug='p37-historico'),false);
 perform pg_temp.require((select count(*)=(select total from p37_notice_baseline) from notifications where project_id=(select id from projects where slug='p37-historico')),'legacy reconciliation is idempotent and quiet');
 insert into profiles(id,full_name) values(leader,'Synthetic Leader'),(member,'Synthetic Member'),(candidate,'Synthetic Candidate'),(outsider,'Synthetic Outsider');
 insert into projects(id,owner_id,title,slug,short_description,description,status) values(p,leader,'Lifecycle synthetic','p37-'||p,'Short','Full','in_progress');
 insert into project_members(project_id,user_id,role,status) values(p,leader,'owner','active'),(p,member,'member','active') on conflict do nothing;
 insert into project_recruitment_roles(project_id,user_id,level) values(p,leader,'owner'),(p,member,'member') on conflict do nothing;
 insert into project_workspace_modules(project_id,module) values(p,'activities') on conflict do nothing;
 insert into project_conversations(id,project_id,kind,status,title)values(conversation,p,'general','active','Geral');
 insert into project_conversation_members(conversation_id,user_id,role)values(conversation,leader,'admin'),(conversation,member,'member');
 insert into project_conversations(id,project_id,kind,status,title)values(secret_group,p,'group','active','Restricted synthetic group');
 insert into project_conversation_members(conversation_id,user_id,role)values(secret_group,leader,'admin');
 insert into project_messages(conversation_id,sender_id,content)values(conversation,leader,'Preserved project history');
 select id into period from activity_periods where project_id=p and is_active;
 if period is null then insert into activity_periods(project_id,name,is_active,created_by)values(p,'2026.2',true,leader)returning id into period;end if;
 select id into stage from activity_stages where project_id=p and kind='todo' limit 1;
 insert into activity_tasks(project_id,period_id,title,stage_id,assignees)values(p,period,'Preserved activity',stage,array[member])returning id into task;
 insert into project_vacancies(project_id,title,positions,open) values(p,'Open role',2,true) returning id into v;
 insert into join_requests(project_id,user_id,message,status)values(p,candidate,'Preserve future application','pending') returning id into request;
 insert into push_devices(user_id,active)values(member,true);
 insert into notifications(id,recipient_id,actor_id,project_id,notification_type,title,body)values(message_notice,member,leader,p,'chat_message','Message','Synthetic message'),(other_notice,member,leader,p,'friend_accepted','Friend accepted','Synthetic event');
 execute 'set local role authenticated';perform set_config('request.jwt.claim.sub',member::text,true);
 perform pg_temp.require((select count(*)=0 from get_my_notifications()where id=message_notice),'message events excluded from bell list');
 perform pg_temp.require(get_my_unread_notifications_count()=1,'bell count excludes same message events');
 perform mark_all_notifications_read();perform pg_temp.require(get_my_unread_notifications_count()=0,'mark visible bell notifications only');
 perform pg_temp.require((select count(*)=1 from get_my_chat_projects()where project_id=p),'active project is operational in chat');
 perform pg_temp.require(get_my_chat_directory()::text not like '%Restricted synthetic group%','unified search never exposes an unauthorized group title');
 execute 'reset role';
 perform pg_temp.require((select read_at is null from notifications where id=message_notice),'hidden message notification preserved and unread');
 perform pg_temp.require((select count(*)=1 from push_outbox where notification_id=message_notice),'message push still queued despite hidden bell event');
 select jsonb_build_object('task',(select to_jsonb(t)from activity_tasks t where id=task),'messages',(select jsonb_agg(m order by id)from project_messages m where conversation_id=conversation)) into snapshot;
 select id,nome into concept,label from conceitos where status='validado' order by id limit 1;
 form:=jsonb_build_object('p_project_id',p,'p_slug','p37-'||p,'p_title','Lifecycle synthetic','p_category','Robótica','p_secondary_categories','[]'::jsonb,'p_project_url',null,'p_short_description','Short','p_description','Full','p_status','completed','p_visibility','public','p_vacancies','[]'::jsonb);
 execute 'set local role authenticated';perform set_config('request.jwt.claim.sub',leader::text,true);
 perform pg_temp.require(get_my_chat_directory()::text like '%Restricted synthetic group%','authorized group titles included in unified search');
 -- Exercise the actual outer form RPC, including its concept writes before finalization.
 perform save_project_concepts(form,null,jsonb_build_array(jsonb_build_object('id',concept,'label',label)));
 perform pg_temp.require((select count(*)=0 from get_my_chat_projects()where project_id=p),'historical project absent from operational chat');
 perform pg_temp.require(not exists(select 1 from jsonb_array_elements(get_my_project_navigation()->'items')x where x->>'id'=p::text),'historical project absent from sidebar');
 perform pg_temp.require((get_activity_dialog(task,p,null)->>'projectReadOnly')::boolean,'shared activity window reports project read-only');
 perform pg_temp.require(get_historical_project('p37-'||p)->>'id'=p::text,'authorized project history available');
 perform pg_temp.require((get_historical_chat_project(p)->>'readOnly')::boolean,'authorized conversation history remains available');
 failed:=false;begin perform mutate_activity(p,'comment',jsonb_build_object('id',task,'body','Forbidden'));exception when raise_exception then failed:=true;end;perform pg_temp.require(failed,'activity discussion writes blocked after finalization');
 failed:=false;begin perform recruitment_save_vacancy(p,v,'Open role','',array[]::text[],2,true);exception when raise_exception then failed:=true;end;perform pg_temp.require(failed,'direct vacancy RPC cannot reopen historic role');
 failed:=false;begin insert into project_messages(conversation_id,sender_id,content)values(conversation,leader,'Forbidden');exception when raise_exception then failed:=true;end;perform pg_temp.require(failed,'direct message API insert blocked');
 failed:=false;begin update projects set status='in_progress' where id=p;exception when raise_exception then failed:=true;end;perform pg_temp.require(failed,'normal update cannot reopen completed project');
 perform set_config('request.jwt.claim.sub',outsider::text,true);perform pg_temp.require(get_historical_project('p37-'||p) is null and get_historical_chat_project(p) is null,'outsider cannot retrieve private history');
 execute 'reset role';
 perform pg_temp.require((select status='closed' and closure_reason='project_completed' and decided_at is null and message='Preserve future application' from join_requests where id=request),'pending candidacy closed explicitly without inventing a rejection decision');
 perform pg_temp.require((select not open and positions=2 from project_vacancies where id=v),'roles closed without changing historical capacity');
 perform pg_temp.require((select count(*)=1 from notifications where join_request_id=request and recipient_id=candidate and title='Projeto encerrado'),'affected candidate notified once');
 perform pg_temp.require((select closed_at is not null from projects where id=p),'new completion timestamp recorded');
 perform pg_temp.require(snapshot=jsonb_build_object('task',(select to_jsonb(t)from activity_tasks t where id=task),'messages',(select jsonb_agg(m order by id)from project_messages m where conversation_id=conversation)),'activity and message data preserved');
 select count(*) into count_before from notifications where join_request_id=request;
 perform lifecycle_private.close_recruitment(p,true);perform pg_temp.require((select count(*)=count_before from notifications where join_request_id=request),'repeated closure never duplicates notifications');
end $$;
rollback;
